+const quizForm = document.getElementById('quizForm');
+const resultContainer = document.getElementById('result');
+const resultText = document.getElementById('resultText');
+
+const correctAnswers = {
+    q1: ['python', 'javascript'],
+    q2: ['cpp', 'go'],
+    q3: ['javascript', 'haskell', 'csharp']
+};
+
+quizForm.addEventListener('submit', function (e) {
+    e.preventDefault();
+
+    const userAnswers = {
+        q1: getCheckedValues('q1'),
+        q2: getCheckedValues('q2'),
+        q3: getCheckedValues('q3')
+    };
+
+    const score = calculateScore(userAnswers);
+    displayResults(score);
+});
+
+function getCheckedValues(questionName) {
+    const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
+    return Array.from(checkboxes).map(checkbox => checkbox.value);
+}
+
+function calculateScore(userAnswers) {
+    let correctCount = 0;
+
+    for (const question in correctAnswers) {
+        const correct = correctAnswers[question];
+        const userAnswer = userAnswers[question];
+
+        if (arraysEqual(correct, userAnswer)) {
+            correctCount++;
+        }
+    }
+
+    return correctCount;
+}
+
+function arraysEqual(a, b) {
+    if (a.length !== b.length) return false;
+    return a.sort().every((val, i) => val === b.sort()[i]);
+}
+
+function displayResults(score) {
+    quizForm.style.display = 'none';
+    resultContainer.style.display = 'block';
+
+    const percentage = (score / 3) * 100;
+    let message = '';
+
+    if (score === 3) {
+        message = `Perfect! You scored ${score}/3 (${Math.round(percentage)}%). You're a programming languages expert! 🎉`;
+    } else if (score === 2) {
+        message = `Great job! You scored ${score}/3 (${Math.round(percentage)}%). You have a solid understanding of programming languages. 👏`;
+    } else if (score === 1) {
+        message = `Good effort! You scored ${score}/3 (${Math.round(percentage)}%). Keep learning about programming languages! 📚`;
+    } else {
+        message = `You scored ${score}/3 (${Math.round(percentage)}%). Don't worry, there's always room to learn! 💪`;
+    }
+
+    resultText.textContent = message;
+}
+
